package com.group49.support.servlet;
import com.group49.support.dao.NotificationDao;import com.group49.support.model.User;import com.group49.support.util.WebUtil;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;
@WebServlet("/notifications") public class NotificationServlet extends HttpServlet{private final NotificationDao notifications=new NotificationDao();
 @Override protected void doGet(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{User u=WebUtil.currentUser(req);try{req.setAttribute("notifications",notifications.list(u.id()));req.setAttribute("unreadCount",notifications.unreadCount(u.id()));req.getRequestDispatcher("/WEB-INF/views/notifications/list.jsp").forward(req,res);}catch(Exception e){throw new ServletException(e);}}
 @Override protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException,ServletException{User u=WebUtil.currentUser(req);try{String action=WebUtil.value(req.getParameter("action"));if("all".equals(action))notifications.markRead(u.id(),null);else if("delete".equals(action))notifications.delete(u.id(),WebUtil.parseInt(req.getParameter("id"),0));else notifications.markRead(u.id(),WebUtil.parseInt(req.getParameter("id"),0));res.sendRedirect(req.getContextPath()+"/notifications");}catch(Exception e){throw new ServletException(e);}}
}
